mapper.sql:
SELECT ssi.ID AS ID, ssi.create_user_id AS createUserId, ssi.create_user_name AS createUserName, ssi.create_time AS createTime, ssi.update_user_id AS updateUserId, ssi.update_user_name AS updateUserName, ssi.update_time AS updateTime, ssi.VERSION AS VERSION, ssi.is_deleted AS isDeleted, ssi.code AS code, ssi.approve_status AS approveStatus, ssi.approve_time AS approveTime, ssi.approve_user_id AS approveUserId, ssi.approve_user_name AS approveUserName, ssi.invalid_status AS invalidStatus, ssi.scrap_user_id AS scrapUserId, ssi.scrap_user_name AS scrapUserName, ssi.scrap_dept_id AS scrapDeptId, ssi.scrap_dept_name AS scrapDeptName, ssi.scrap_date AS scrapDate, ssi.remark AS remark, ssid.id as detailId, ssid.sku_id as skuId, ssid.sku_no as skuNo, ssid.product_name as productName, ssid.scrap_qty as scrapQty, ssid.remark as detailRemark FROM sample_scrap_info AS ssi LEFT JOIN sample_scrap_detail AS ssid ON ssid.main_id = ssi.ID AND ssid.is_deleted = FALSE WHERE ${params.sqlMap.default} AND ssi.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ssi.create_time desc

mapper.select:
SELECT ssi.approve_status AS tabFlag, count(*) AS count FROM sample_scrap_info ssi WHERE ssi.is_deleted=FALSE
${params.permissionSql}
GROUP BY ssi.approve_status
